  * (`selectPdpProductInfo`, proven in pages/product-detail/productInfo.test.ts) and this atom
@@ -21,6 +21,25 @@ describe('ZimmProductPrice', () => {
     expect(screen.getByTestId('product-price').textContent).toBe('HK$6,200.00');
   });

+  test('announces the price through a polite atomic live region', () => {
+    const { container } = render(<ZimmProductPrice price="HK$6,200.00" />);
+
+    // A variant change swaps this string with no focus move, so WCAG 2.2 AA 4.1.3 needs the
+    // update announced. Both attributes are asserted: dropping `aria-atomic` would let a screen
+    // reader announce only the characters that differ instead of the whole price, and neither
+    // loss shows up on screen, so nothing else would catch it.
+    const price = screen.getByTestId('product-price');
+    expect(price).toHaveAttribute('aria-live', 'polite');
+    expect(price).toHaveAttribute('aria-atomic', 'true');
+
+    // The live region is the price element itself, not an extra hidden twin. Asserted because
+    // the single-node shape is load-bearing, not incidental: `ZimmProductContent` renders this
+    // atom into a flex column whose own `play` tests assert that column's exact child count, so
+    // a second node here fails them from another folder.
+    expect(container.querySelectorAll('[aria-live]')).toHaveLength(1);
+    expect(container.firstChild).toBe(price);
+  });
+
   test.each([undefined, ''])('renders nothing for %s', (price) => {
     const { container } = render(<ZimmProductPrice price={price} />);
     // `''` is what the page's mapper produces for a product with no price, so this branch is
diff --git a/overrides/app/components/ui-kits/atoms/zimmProductPrice/index.tsx b/overrides/app/components/ui-kits/atoms/zimmProductPrice/index.tsx
index e84b6de..d6c95ad 100644
--- a/overrides/app/components/ui-kits/atoms/zimmProductPrice/index.tsx
+++ b/overrides/app/components/ui-kits/atoms/zimmProductPrice/index.tsx
@@ -35,7 +35,28 @@ export const ZimmProductPrice = ({ price, variant = 'default' }: ZimmProductPric
   if (!price) return null;

   return (
-    <chakra.p __css={styles} textStyle="price" data-testid="product-price">
+    /*
+     * `aria-live`/`aria-atomic` sit on the price element itself, so this atom still renders
+     * exactly one node.
+     *
+     * WCAG 2.2 AA 4.1.3 (Status Messages) is the requirement. Choosing a variant rewrites the
+     * URL's `pid` (`pages/product-detail/index.tsx` lines 328-338), which re-keys the
+     * `useProduct` call on line 205 and hands this atom a different string. Focus never moves,
+     * so without a live region the price is repainted silently and a screen-reader user is never
+     * told the number they are buying at has changed. React mutates this element's text in
+     * place, which is exactly the change a live region reports; `aria-atomic` makes it read the
+     * whole price rather than only the characters that differ.
+     *
+     * Base `display-price/current-price.jsx` instead puts the announcement in a second, hidden
+     * node (its lines 57-66). It needs one because it prefixes a `labelForA11y` product name to
+     * order the name ahead of the price (its comment on line 56); this atom has no such prefix
+     * to order — `price` arrives already formatted and localised by the page and there is no
+     * `useIntl` here — so the extra node would carry a verbatim duplicate of the visible text.
+     * That costs twice: every screen reader would read the price twice on first load, and the
+     * extra child breaks `ZimmProductContent`'s `play` tests, which assert the exact child count
+     * of its flex column (`WithoutDescription`, `RhythmWithDescription`, `BlankDescription`).
+     */
+    <chakra.p __css={styles} textStyle="price" data-testid="product-price" aria-live="polite" aria-atomic="true">
       {price}
     </chakra.p>
   );

