   useProduct,
   useProducts,
@@ -58,7 +61,18 @@ import RecommendedProducts from '@salesforce/retail-react-app/app/components/rec
  * override, because their issuer is inside node_modules and so is redirected normally.
  */
 import ProductView from '../../components/product-view';
-import type { ChildProductOrderability, ProductViewRefScope } from '../../components/product-view';
