+  ChildProductOrderability,
+  ProductViewHeaderProps,
+  ProductViewRefScope,
+} from '../../components/product-view';
+import Breadcrumb from '@salesforce/retail-react-app/app/components/breadcrumb';
+import PromoCallout from '@salesforce/retail-react-app/app/components/product-tile/promo-callout';
+
+// SFCC-89 — static product information.
+import { ZimmProductContent } from '../../components/ui-kits/molecules/zimmProductContent';
+import { ZimmProductMeta } from '../../components/ui-kits/molecules/zimmProductMeta';
+import { selectPdpProductInfo } from './productInfo';
