+  // `formatMessage` alone. It feeds `formatPrice` below.
   // eslint-disable-next-line @typescript-eslint/unbound-method
-  const { formatMessage } = useIntl();
+  const { formatMessage, formatNumber } = useIntl();
   const history = useHistory();
   const location = useLocation();
   const einstein = useEinstein();
@@ -691,6 +706,83 @@ const ProductDetail = () => {
     }
   }, [product]);

+  /**************** SFCC-89 — static product information ****************/
+  const formatPrice = (amount: number, priceCurrency: string) =>
+    formatNumber(amount, { style: 'currency', currency: priceCurrency });
+
+  /**
+   * Replaces the title/price block of ProductView's header with the Zimmermann content group.
+   *
+   * The breadcrumb and promo callout are reproduced from the base header rather than dropped:
+   * `renderHeader` replaces the whole header block, and neither of those belongs to SFCC-89
+   * (breadcrumb is SFCC-578, badges are SFCC-132/225), so losing them here would be a
+   * regression rather than a scope decision.
+   *
+   * ProductView calls this once per breakpoint, so it stays pure.
+   */
+  const renderStaticProductHeader = ({
+    name,
+    product: headerProduct,
+    priceData,
+    currency,
+    category: headerCategory,
+    isProductPartOfBundle,
+  }: ProductViewHeaderProps) => {
+    const info = selectPdpProductInfo(headerProduct ?? { name }, priceData, currency ?? '', formatPrice);
+
+    return (
+      <VStack mr={4} spacing={2} align="flex-start" marginBottom={[4, 4, 4, 0, 0]}>
+        {headerCategory && (
+          <Skeleton isLoaded={headerCategory} minWidth={64}>
+            <Breadcrumb categories={headerCategory} />
+          </Skeleton>
+        )}
+
+        {/*
+         * `minHeight` reserves the name's line box, so the title does not shove the page down
+         * when it resolves. SFCC's `Skeleton` baseStyle sets only `borderRadius` and `opacity`,
+         * so an empty one measures 0px; the base header avoids that by interpolating the name
+         * into a template, which stringifies `undefined` to "undefined" and is therefore always
+         * title-height. The value is the name's own line-height: `ZimmProductName` renders at
+         * `textStyle="heading3"`, whose `lineHeight` is `lineHeights['2xs']` (1.125rem / 18px) —
+         * the same entry `--zimm-font-lineheight-2xs` is derived from.
+         *
+         * This reserves ONE line, matching base. A name that wraps still shifts by ~18px, and
+         * wrapping is a real case — the design caps the name at 180px inside a 218px column and
+         * `zimmProductName/index.stories.tsx` ships a story for it. Reserving two lines would
+         * over-reserve for every single-line product and exceed base's own behaviour, which
+         * AGENTS.md's minimal-changes rule rules out.
+         */}
+        <Skeleton isLoaded={Boolean(info)} minHeight="var(--zimm-font-lineheight-2xs)">
+          {info && (
+            // h2, not h1: the page already emits a screen-reader-only
+            // <h1>Product Details</h1>, and the base header this replaces rendered the name
+            // as an h2. Changing the outline is SEO's call, not a side-effect of this ticket.
+            <ZimmProductContent
+              name={info.name}
+              headingLevel="h2"
+              // The base header gates its price and its promo together behind the same
+              // `!isProductPartOfBundle` check. The promo is gated below; without this the
+              // price would be the one part of that header which stopped being gated.
+              price={isProductPartOfBundle ? undefined : info.price}
+              description={info.description}
+            />
+          )}
+        </Skeleton>
+
+        {!isProductPartOfBundle && (
+          <Skeleton isLoaded={Boolean(headerProduct)}>
+            {headerProduct?.productPromotions && <PromoCallout product={headerProduct} />}
+          </Skeleton>
+        )}
+      </VStack>
+    );
+  };
+
+  // Model copy and the style code are not part of the content group: the design places them at
+  // the foot of the column, below the accordions, so the page positions them itself.
+  const staticInfo = selectPdpProductInfo(product, null, product?.currency ?? '', formatPrice);
+
   return (
     <Box className="sf-product-detail-page" layerStyle="page" data-testid="product-details-page">
       <Heading as="h1" srOnly>
@@ -739,22 +831,14 @@ const ProductDetail = () => {
                   <Box key={childProduct.id} data-testid="child-product">
                     <ProductView
                       // Do not use an arrow function as we are manipulating the functions scope.
-                      // The double assertion is documentation, not a required suppression: it
-                      // records that ProductView rebinds `this` to a `ProductViewRefScope` on this
-                      // callback, which React's own `Ref<T>` has no way to express. TypeScript
-                      // accepts the function as a ref without it (verified — removing the cast
-                      // leaves `tsc --noEmit` clean), so the assertion is inert and cannot alter
-                      // what React receives.
-                      ref={
-                        function (this: ProductViewRefScope, ref: ChildProductRef['ref']) {
-                          // Assign the "set" scope of the ref, this is how we access the internal
-                          // validation.
-                          childProductRefs.current[childProduct.id] = {
-                            ref,
-                            validateOrderability: this.validateOrderability,
-                          };
-                        } as unknown as React.Ref<HTMLDivElement>
-                      }
+                      ref={function (this: ProductViewRefScope, ref: ChildProductRef['ref']) {
+                        // Assign the "set" scope of the ref, this is how we access the internal
+                        // validation.
+                        childProductRefs.current[childProduct.id] = {
+                          ref,
+                          validateOrderability: this.validateOrderability,
+                        };
+                      }}
                       product={childProduct}
                       isProductPartOfSet={isProductASet}
                       isProductPartOfBundle={isProductABundle}
@@ -812,6 +896,7 @@ const ProductDetail = () => {
               <ProductView
                 product={product}
                 category={primaryCategory?.parentCategoryTree || []}
+                renderHeader={renderStaticProductHeader}
                 addToCart={handleAddToCart}
                 addToWishlist={handleAddToWishlist}
                 isProductLoading={isProductLoading}
@@ -826,7 +911,21 @@ const ProductDetail = () => {
                 onOpenStoreLocator={onOpenStoreLocator}
                 showDeliveryOptions={storeLocatorEnabled}
               />
-              <InformationAccordion product={product} />
+              {/*
+               * The accordions and the meta block deliberately share one `<Box>`, so the pair is a
+               * single flex item of the outer `<Stack spacing={16}>` rather than two. Chakra spaces
+               * a Stack with `gap` rather than a child selector, and `<Island>` emits no element of
+               * its own while `partialHydrationEnabled` is false, so anything left unwrapped in
+               * here is a direct child taking a 64px push from its neighbour. Sharing one item
+               * lands that 64px above the pair instead of between them, which leaves
+               * `ZimmProductMeta`'s recipe owning both 28px hops — the one below the accordions and
+               * the one between its own two rows. Hence no spacing props on the Box. The molecule
+               * returns null when it has neither value to show.
+               */}
+              <Box>
+                <InformationAccordion product={product} />
+                <ZimmProductMeta modelInfo={staticInfo?.modelInfo} styleCode={staticInfo?.styleCode} />
+              </Box>
             </Island>
           </Fragment>
         )}

