     3	import { zimmTokens } from './foundation/zimmTokens';
     4	
     5	// Injects the --zimm-* custom properties onto :root via a raw Emotion <Global>.
     6	//
     7	// Deliberately NOT Chakra's styles.global: Chakra's style processor mangles quoted
     8	// font-family values (verified — "'Futura Round', 'Century Gothic', sans-serif"
     9	// collapses to a single family), which would break the --zimm-font-family-* vars.
    10	// A raw Emotion <Global> preserves them.
    11	//
    12	// Rendered in the app by _app-config/index.tsx AND in Storybook by
    13	// .storybook/preview.tsx, so the .zimm-* global classes and the var(--zimm-*)
    14	// component overrides resolve identically in both. Kept as one shared definition
    15	// so the two mount points cannot drift.
    16	export const zimmRootVarsCss = css`
    17	  :root {
    18	    ${Object.entries(zimmTokens)
    19	      .map(([k, v]) => `${k}:${v}`)
    20	      .join(';')}
    21	  }
    22	`;
    23	
    24	/** Injects the --zimm-* :root custom properties. Render once, high in the tree. */
    25	export function ZimmTokensGlobal(): React.ReactElement {
    26	  return <Global styles={zimmRootVarsCss} />;
    27	}
