try{r.writeHead(200,{'Content-Type':f.endsWith('.js')?'text/javascript':'text/html'});r.end(fs.readFileSync('/tmp/pdpprobe'+f));}catch{r.writeHead(404);r.end();}});
await new Promise(r=>srv.listen(9914,r));
const b=await chromium.launch();
for (const v of ['real','mut']) {
  fs.writeFileSync('/tmp/pdpprobe/index3.html', fs.readFileSync('/tmp/pdpprobe/index.html','utf8').replace('/bundle.js', `/bundle3_${v}.js`));
  const page=await b.newPage(); page.on('pageerror',e=>console.log('[err]',String(e).slice(0,200)));
  await page.goto('http://127.0.0.1:9914/'); await page.waitForSelector('[data-testid="product-price"]');
  const before = await page.evaluate(()=>{const p=document.querySelector('[data-testid="product-price"]');
    return {tag:p.tagName, ariaLive:p.getAttribute('aria-live'), ariaAtomic:p.getAttribute('aria-atomic'),
      ariaLabel:p.getAttribute('aria-label'), text:p.textContent,
      liveNodeCount:document.querySelectorAll('[aria-live]').length,
      contentChildren:document.querySelector('[data-testid="product-content"]').children.length,
      nodeId:(p.__id=Math.random().toString(36).slice(2))};});
  await page.evaluate(()=>window.__swap());
  await page.waitForTimeout(150);
  const after = await page.evaluate(()=>{const p=document.querySelector('[data-testid="product-price"]');
    return {text:p.textContent, sameNode:p.__id!==undefined, ariaLive:p.getAttribute('aria-live')};});
  console.log(v.toUpperCase().padEnd(5), JSON.stringify({before,after}));
  await page.close();
}
await b.close(); srv.close();
